<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Domains zu Auftragsposition</title><style>body{font:14px Segoe UI,Arial;background:#f4f6f8;color:#1f2937;padding:24px}.page{max-width:1250px;margin:auto}.top{display:flex;justify-content:space-between}.cols{display:grid;grid-template-columns:360px 1fr;gap:18px}.card{background:#fff;border:1px solid #ddd;border-radius:10px;padding:18px}.list{max-height:420px;overflow:auto;border:1px solid #ddd}.item{display:block;padding:8px;border-bottom:1px solid #eee;color:#111;text-decoration:none}.sel{background:#eef4ff}.button{display:inline-block;padding:8px 12px;border:1px solid #aaa;border-radius:6px;background:#fff;color:#111;text-decoration:none}.grid{display:grid;grid-template-columns:150px 1fr;gap:8px}table{width:100%;border-collapse:collapse}th,td{padding:7px;border-bottom:1px solid #ddd;text-align:left}.ok,.err{padding:8px;margin-bottom:10px}.ok{background:#ecfdf5}.err{background:#fef2f2}.muted{color:#666;font-size:12px}</style></head><body><div class="page"><div class="top"><h1>Domains zu Auftragsposition</h1><a href="{{route('frontend.switch','classic')}}">← Zur klassischen Ansicht</a></div>@if(session('status'))<div class="ok">{{session('status')}}</div>@endif @if($errors->any())<div class="err">{{implode(' · ',$errors->all())}}</div>@endif<div class="cols"><div class="card"><form><input name="kunde" value="{{$customerFilter}}" placeholder="Kundennr."><input name="domain" value="{{$domainFilter}}" placeholder="Domain"><button class="button">Suchen</button></form><h3>Nicht zugeordnete Domains</h3><div class="list">@foreach($domains as $d)<a class="item {{$selected&&$selected->intID==$d->intID?'sel':''}}" href="{{route('domain-order.index',['domain_id'=>$d->intID,'kunde'=>$customerFilter,'domain'=>$domainFilter])}}"><b>{{trim($d->strDomainname)}}</b><br>Kunde {{$d->UMSTELLUNGintKundenID}} · {{trim($d->kunde->strName ?? '')}}</a>@endforeach</div></div><div class="card">@if($selected)<div class="grid"><b>